from __future__ import annotations

import base64
import io
from PIL import Image

IMMICH_ICON_120_PNG_B64 = ""
IMMICH_ICON_48_PNG_B64 = ""

ICON_120_PNG = base64.b64decode(IMMICH_ICON_120_PNG_B64)
ICON_48_PNG = base64.b64decode(IMMICH_ICON_48_PNG_B64)


def _resize_png(png_bytes: bytes, size: int) -> bytes:
    with Image.open(io.BytesIO(png_bytes)) as im:
        resized = im.resize((size, size), Image.Resampling.LANCZOS)
        buf = io.BytesIO()
        resized.save(buf, format="PNG")
        return buf.getvalue()


def _png_to_jpeg(png_bytes: bytes) -> bytes:
    with Image.open(io.BytesIO(png_bytes)) as im:
        rgb = Image.new("RGB", im.size, (255, 255, 255))
        if im.mode == "RGBA":
            rgb.paste(im, mask=im.split()[3])
        else:
            rgb.paste(im)
        buf = io.BytesIO()
        rgb.save(buf, format="JPEG", quality=95)
        return buf.getvalue()


def _png_to_bmp(png_bytes: bytes) -> bytes:
    with Image.open(io.BytesIO(png_bytes)) as im:
        rgb = Image.new("RGB", im.size, (255, 255, 255))
        if im.mode == "RGBA":
            rgb.paste(im, mask=im.split()[3])
        else:
            rgb.paste(im)
        buf = io.BytesIO()
        rgb.save(buf, format="BMP")
        return buf.getvalue()


ICON_32_PNG = _resize_png(ICON_48_PNG, 32)

ICON_120_JPEG = _png_to_jpeg(ICON_120_PNG)
ICON_48_JPEG = _png_to_jpeg(ICON_48_PNG)
ICON_32_JPEG = _png_to_jpeg(ICON_32_PNG)

ICON_120_BMP = _png_to_bmp(ICON_120_PNG)
ICON_48_BMP = _png_to_bmp(ICON_48_PNG)
ICON_32_BMP = _png_to_bmp(ICON_32_PNG)

